/// The catalog spec of `idname` (`"mesh.bevel"`), if it is a catalog operator (decodes the
/// blob on first use; the address is stable for the process).
pub fn find(idname: &str) -> Option<&'static frap_rna::OperatorSpec> {
    let c = crate::catalog();
    c.binary_search_by(|s| s.idname.cmp(idname)).ok().map(|i| c[i])
}

/// True when `idname` is a catalog operator (no decoding).
pub fn contains(idname: &str) -> bool {
    CATALOG_IDNAMES.binary_search(&idname).is_ok()
}

/// True when `idname` has a typed props struct in `frap-spec-ops-<group>`.
pub fn is_typed(idname: &str) -> bool {
    TYPED_IDNAMES.binary_search(&idname).is_ok()
}
